sql.where:
o.deleted = 0

    AND (o.order_no ILIKE '%' || #{q.keyword} || '%'
         OR c.name    ILIKE '%' || #{q.keyword} || '%')


    AND o.warehouse_id = #{q.warehouseId}


    AND o.customer_id = #{q.customerId}


    AND o.status = #{q.status}


    AND o.created_at >= #{q.startTime}


    AND o.created_at <= #{q.endTime}

mapper.select:
SELECT 
FROM wms_outbound_order o
JOIN wms_warehouse w ON w.id = o.warehouse_id
LEFT JOIN wms_customer c ON c.id = o.customer_id

${q.orderByClause}
LIMIT #{q.resolvedSize} OFFSET #{q.offset}

